/* Minimal Bootstrap bundle stub used as offline fallback.
   This does not implement Bootstrap. It simply creates a `bootstrap` namespace
   so templates or small scripts checking `bootstrap` don't throw when CDN is blocked.
*/
window.bootstrap = window.bootstrap || {};
window.bootstrap.Tooltip = function(){};
window.bootstrap.Modal = function(){};
window.bootstrap.collapse = function(){};
// mark version
window.bootstrap.VERSION = '5.1.3-fallback';
